  current,
  assistantName,
  session,
}: {
  slug: string;
  features: NavFeatures;
  current: NavPage;
  /** The assistant's name: on a guest page the chat link reads "Need help? Ask <name>" (D-136 amended). */
  assistantName?: string;
  session?: { auth: SessionState; role: Role | null; onLogout: () => void };
}) {
  const api = `/api/t/${slug}`;
  const [own, setOwn] = useState<{ auth: SessionState; role: Role | null }>({ auth: 'checking', role: null });

  useEffect(() => {
    if (session) return;
    void fetchRole(api).then((role) => setOwn({ auth: role ? 'in' : 'out', role }));
  }, [api, session]);

  const ownLogout = useCallback(async () => {
    await fetch(`${api}/admin/session`, { method: 'DELETE' }).catch(() => undefined);
    setOwn({ auth: 'out', role: null });
  }, [api]);

  const auth = session?.auth ?? own.auth;
  const role = auth === 'in' ? (session?.role ?? own.role) : null;
  const logout = session?.onLogout ?? ownLogout;
  const publicPage = current === 'chat' || current === 'book' || current === 'manage' || current === 'reset' || current === 'legal';

  const all = navItems(slug, features, role);
  const isPublic = (page: NavPage) => page === 'chat' || page === 'book' || page === 'manage';
  // D-136: the three guest pages link to each other. A guest page's header
  // shows the OTHER guest pages (its own link is left out); a signed-out
  // staff page's header shows Chat alone, as before (the user, 2026-10-14:
  // a Book button there was redundant).
  const shown = publicPage ? all.filter((item) => isPublic(item.page) && item.page !== current) : all.filter((item) => item.page !== 'book' && item.page !== 'manage');
  const staffHome = publicPage ? all.find((item) => !isPublic(item.page)) : undefined;

  return (
    <>
      {shown.map((item) => (
        <Link
          key={item.page}
          className={item.primary ? 'button primary' : 'button'}
          href={item.href}
          aria-current={item.page === current ? 'page' : undefined}
        >
          {publicPage && item.page === 'chat' && <Icon name="chat" size={16} />}
          {publicPage && item.page === 'chat' ? chatLinkLabel(assistantName) : item.label}
        </Link>
      ))}
      {staffHome && (
        <Link className="button" href={staffHome.href}>
          <Icon name="chart" size={16} />
          <span className="narrow-hidden">{staffHome.label}</span>
        </Link>
      )}
      {auth === 'in' && (
        <button type="button" className="link" onClick={logout}>
          Log out
        </button>
      )}
    </>
  );
}

